// Session API tests: time/header, manual measurement, notes/exclusions, Track & Stack, detection list, dark/flat.
// Data: bundled example cpp/gui/assets/example (3 ZTF frames of (5157) Hindemith + Gaia DR3); synthetic SBIG, dark and
// flat generated by the test itself.
// Uso: test_measure [raiz-do-repo]
#include "../src/session_internal.hpp"
#include "piazzi/astro_c.h"
#include "piazzi/core.hpp"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

static int fails = 0;
#define CHECK(c, ...)                                                                                                                      \
    do {                                                                                                                                   \
        if (!(c)) {                                                                                                                        \
            ++fails;                                                                                                                       \
            std::printf("FAIL: " __VA_ARGS__);                                                                                             \
            std::printf("  [%s:%d]\n", __FILE__, __LINE__);                                                                                \
        }                                                                                                                                  \
    } while (0)

static AstroSession *make(const std::string &root) {
    AstroSession *s = astro_new();
    astro_load_cfg(s, (root + "/cpp/gui/assets/example/example.cfg").c_str());
    astro_set(s, "observer", "Test");
    astro_set(s, "measurer", "Test");
    astro_set(s, "submitter", "Test");
    for (int i = 0; i < 3; ++i)
        astro_add_image(s, (root + "/cpp/gui/assets/example/ztf_hindemith_" + std::to_string(i) + ".fits").c_str());
    return s;
}
static int reduce(AstroSession *s, const std::string &root) {
    return astro_reduce(s, (root + "/cpp/gui/assets/example/gaia_dr3.tsv").c_str(), "07 11 43.534", "+22 24 17.78", "5157");
}
static int count(const std::string &h, const std::string &n) {
    int c = 0;
    for (size_t p = h.find(n); p != std::string::npos; p = h.find(n, p + 1))
        ++c;
    return c;
}

// minimal 16-bit FITS (BZERO 32768) with a constant value or a pixel function
static void write_fits(const std::string &path, int w, int h, const std::vector<int> &v) {
    std::string hd;
    auto card = [&](const std::string &c) {
        std::string x = c;
        x.resize(80, ' ');
        hd += x;
    };
    card("SIMPLE  =                    T");
    card("BITPIX  =                   16");
    card("NAXIS   =                    2");
    card("NAXIS1  = " + std::string(20 - std::to_string(w).size(), ' ') + std::to_string(w));
    card("NAXIS2  = " + std::string(20 - std::to_string(h).size(), ' ') + std::to_string(h));
    card("BZERO   =                32768");
    card("EXPTIME =                 10.0");
    card("DATE-OBS= '2020-01-01T00:00:00'");
    card("END");
    hd.resize((hd.size() + 2879) / 2880 * 2880, ' ');
    std::string data;
    for (int q : v) {
        int r = q - 32768;
        data += char((r >> 8) & 0xFF);
        data += char(r & 0xFF);
    }
    data.resize((data.size() + 2879) / 2880 * 2880, '\0');
    std::ofstream(path, std::ios::binary) << hd << data;
}

int main(int argc, char **argv) {
    std::string root = argc > 1 ? argv[1] : ".";
    // ---------------------------------------------------------------- time and header
    {
        AstroSession *s = make(root);
        CHECK(astro_image_count(s) == 3, "image_count");
        std::string h = astro_image_header(s, 0);
        CHECK(h.find("NAXIS1") != std::string::npos && h.find("EXPTIME") != std::string::npos, "FITS header: %s", h.c_str());
        double jd0 = astro_image_jd(s, 0);
        CHECK(jd0 > 2459251 && jd0 < 2459252, "jd %f", jd0);
        astro_set(s, "time_offset_s", "30");
        CHECK(std::fabs((astro_image_jd(s, 0) - jd0) * 86400 - 30) < 1e-3, "time_offset_s 30 s");
        astro_set(s, "TimeOffsetH", "1");
        astro_set(s, "TimeDelay", "2");
        CHECK(std::fabs((astro_image_jd(s, 0) - jd0) * 86400 - (30 - 3600 + 2)) < 1e-3, "TimeOffsetH/TimeDelay");
        astro_set(s, "time_offset_s", "0");
        astro_set(s, "TimeOffsetH", "0");
        astro_set(s, "TimeDelay", "0");
        astro_set_image_jd(s, 1, 2459250.25);
        CHECK(astro_image_jd(s, 1) == 2459250.25, "override");
        astro_set_image_jd(s, 1, 0);
        CHECK(astro_image_jd(s, 1) != 2459250.25, "override removed");
        astro_free(s);
    }
    // ---------------------------------------------------------------- reduction, manual measurement, notes, exclusions
    AstroSession *s = make(root);
    int nm = reduce(s, root);
    CHECK(nm == 1, "movers %d", nm);
    std::string ades0 = astro_report(s, 0), mpc0 = astro_report(s, 2);
    std::string js = astro_result_json(s);
    // automatic asteroid position in image 1
    double ax = std::atof(js.c_str() + js.find("\"x\":", js.find("\"movers\"")) + 4),
           ay = std::atof(js.c_str() + js.find("\"y\":", js.find("\"movers\"")) + 4);
    double ara = std::atof(js.c_str() + js.find("\"rad\":", js.find("\"movers\"")) + 6),
           adec = std::atof(js.c_str() + js.find("\"decd\":", js.find("\"movers\"")) + 7);
    double out[12];
    CHECK(astro_measure(s, 0, std::round(ax) + 1, std::round(ay) - 1, out) == 1, "measure");
    double dra = (out[0] - ara) * 3600 * std::cos(adec * M_PI / 180), dde = (out[1] - adec) * 3600;
    std::printf("manual measurement: x=%.3f y=%.3f (auto %.3f %.3f) dRA=%.4f\" dDec=%.4f\" mag=%.2f snr=%.1f fwhm=%.2f\"\n", out[5], out[6],
                ax, ay, dra, dde, out[2], out[3], out[4]);
    CHECK(std::hypot(dra, dde) < 0.2, "manual vs automatic %.4f\"", std::hypot(dra, dde));
    CHECK(out[10] > 0 && out[11] > 0, "plate dra/ddec");
    // reference star: must give the O−C residual, not the rms
    std::string cat0 = astro_image_catalog(s, 0);
    CHECK(count(cat0, "\"type\":\"R\"") >= 50 && count(cat0, "\"type\":\"M\"") == 1, "image catalog R=%d M=%d",
          count(cat0, "\"type\":\"R\""), count(cat0, "\"type\":\"M\""));
    int ndet0 = std::atoi(js.c_str() + js.find("\"ndet\":") + 7);
    CHECK(count(cat0, "\"type\":\"r\"") >= 1 && count(cat0, "{\"x\"") == ndet0, "image catalog r / total (%d)", ndet0);
    // position of a reference star in image 1 (first item of "refs")
    size_t rp = js.find("\"refs\":[[") + 9;
    double sx = std::atof(js.c_str() + rp), sy = std::atof(js.c_str() + js.find(',', rp) + 1);
    // manual object: one star in 2 images
    int t = astro_add_manual(s, -1, 0, sx, sy);
    CHECK(t == 1, "add_manual idx %d", t);
    CHECK(astro_add_manual(s, t, 1, sx, sy) == t, "add_manual extend");
    std::string ades1 = astro_report(s, 0), mpc1 = astro_report(s, 2), ph1 = astro_report(s, 1);
    CHECK(count(ades1, "\n5157 ") == 5 && count(mpc1, "\n05157 ") == 5 && count(ph1, "5157") == 5, "manual in reports (%d %d %d)",
          count(ades1, "\n5157 "), count(mpc1, "\n05157 "), count(ph1, "5157"));
    js = astro_result_json(s);
    CHECK(count(js, "\"manual\":true") == 1 && count(js, "\"manual\":false") == 1, "json manual");
    astro_set_note(s, 0, 2, "I");
    std::string mpc2 = astro_report(s, 2);
    CHECK(mpc2.find("05157        IC") != std::string::npos, "MPC note:\n%s", mpc2.c_str());
    CHECK(std::string(astro_report(s, 0)).find("|I    |") != std::string::npos, "ADES note");
    astro_set_excluded(s, 0, 1, 1);
    CHECK(count(astro_report(s, 0), "\n5157 ") == 4 && count(astro_report(s, 2), "\n05157 ") == 4 && count(astro_report(s, 1), "5157") == 4,
          "exclusion");
    js = astro_result_json(s);
    CHECK(count(js, "\"excluded\":true") == 1 && count(js, "\"note\":\"I\"") == 1, "json note/excluded");
    astro_set_excluded(s, 0, 1, 0);
    astro_set_note(s, 0, 2, "");
    // ---------------------------------------------------------------- Track & Stack
    int ks = astro_stack(s, 0.353, 276.6, 1);
    CHECK(ks == 3, "stack idx %d", ks);
    js = astro_result_json(s);
    CHECK(count(js, "\"stacked\":true") == 1, "json stacked");
    std::string cst = astro_image_catalog(s, ks);
    // asteroid detection in the stacked frame, at the image 1 position
    int near = 0;
    double fw = 0, snr = 0, bd = 1e9;
    size_t p = 0;
    while ((p = cst.find("{\"x\":", p)) != std::string::npos) {
        double x = std::atof(cst.c_str() + p + 5), y = std::atof(cst.c_str() + cst.find("\"y\":", p) + 4);
        if (std::hypot(x - ax, y - ay) < 4)
            ++near;
        if (std::hypot(x - ax, y - ay) < std::min(bd, 4.0)) {
            bd = std::hypot(x - ax, y - ay);
            fw = std::atof(cst.c_str() + cst.find("\"fwhm\":", p) + 7);
            snr = std::atof(cst.c_str() + cst.find("\"snr\":", p) + 6);
        }
        ++p;
    }
    std::printf("stack: %d detection(s) near the asteroid, FWHM %.2f\" SNR %.1f\n", near, fw, snr);
    // in the stacked frame the neighboring star becomes a trail; the nearest detection must be the point-like asteroid
    CHECK(near >= 1 && bd < 1.5 && fw > 2 && fw < 8, "sharp asteroid in stack");
    CHECK(astro_measure(s, ks, ax, ay, out) == 1, "measure on stack");
    std::printf("stack: measurement dRA=%.3f\" dDec=%.3f\"\n", (out[0] - ara) * 3600 * std::cos(adec * M_PI / 180), (out[1] - adec) * 3600);
    CHECK(std::hypot((out[0] - ara) * 3600 * std::cos(adec * M_PI / 180), (out[1] - adec) * 3600) < 0.5, "position on stack");
    int tk = astro_add_manual(s, -1, ks, ax, ay);
    std::string mpck = astro_report(s, 2);
    CHECK(tk >= 0 && mpck.find("05157        KC") != std::string::npos, "stack K note:\n%s", mpck.c_str());
    // reducing again clears the manual objects and the reports return to the automatic result
    reduce(s, root);
    CHECK(ades0 == astro_report(s, 0) && mpc0 == astro_report(s, 2), "reports identical after re-reduction");
    astro_free(s);
    // ---------------------------------------------------------------- synthetic dark / flat
    {
        std::string d = "/tmp/astro_test_measure";
        std::system(("mkdir -p " + d).c_str());
        int w = 8, h = 6;
        std::vector<int> li(w * h), dk(w * h, 100), fl(w * h);
        for (int i = 0; i < w * h; ++i) {
            li[i] = 1100 + 10 * i;
            fl[i] = i % 2 ? 2000 : 1000;
        }
        write_fits(d + "/light.fits", w, h, li);
        write_fits(d + "/dark.fits", w, h, dk);
        write_fits(d + "/flat.fits", w, h, fl);
        AstroSession *c = astro_new();
        astro_set(c, "flip_horizontal", "0");
        astro_set(c, "flip_vertical", "0");
        astro_add_image(c, (d + "/light.fits").c_str());
        CHECK(astro_set_dark(c, (d + "/dark.fits").c_str()) == 1 && astro_set_flat(c, (d + "/flat.fits").c_str()) == 1, "set dark/flat");
        CHECK(astro_set_dark(c, (d + "/nao_existe.fits").c_str()) == 0, "missing dark");
        std::string hd = astro_image_header(c, 0);
        CHECK(hd.find("NAXIS1  =                    8") != std::string::npos, "FITS header");
        // mediana do flat = 1500 -> normalizado 0,667 / 1,333
        astro::Image im = session_load_image(c, 0, true);
        bool ok = true;
        for (int i = 0; i < w * h; ++i) {
            double e = std::nearbyint((li[i] - 100.0) / (fl[i] / 1500.0));
            if (im.pix[i] != e)
                ok = false;
        }
        CHECK(ok, "dark/flat applied (pix0=%d expected %.0f)", im.pix[0], std::nearbyint(1000 / (1000 / 1500.0)));
        astro_set_dark(c, "");
        astro_set_flat(c, "");
        im = session_load_image(c, 0, true);
        CHECK(im.pix[0] == 1100, "no calibration");
        astro_free(c);
    }
    std::printf(fails ? "%d FAILURE(S)\n" : "OK\n", fails);
    return fails ? 1 : 0;
}
